cssRules:
.stat-card {
  background: #12141a;
  border: 1px solid #232733;
  border-radius: 8px;
  padding: 16px;
}
.stat-label {
  font-size: 12px;
  color: #8f96a3;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.stat-value {
  font-size: 28px;
  font-weight: 700;
  font-family: ui-monospace, monospace;
  color: #ffffff;
  margin: 6px 0;
  display: flex;
  align-items: baseline;
  gap: 8px;
}
.stat-badge {
  font-size: 11px;
  padding: 2px 6px;
  border-radius: 4px;
  background: rgba(34, 197, 94, 0.15);
  color: #4ade80;
  border: 1px solid rgba(34, 197, 94, 0.3);
}
.stat-sub {
  font-size: 11px;
  color: #636b7b;
}
